// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        // Ensure the external call does not revert (we only consider successful calls)
        bool success;
        bytes memory returnData;
        (success, returnData) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, caddress, _tos, v));
        vm.assume(success);
        // Decode the return value
        bool retVal = abi.decode(returnData, (bool));
        // The reference always returns true (the require condition is true)
        assertTrue(retVal == true);
    }
}

